+  @Test
+  @org.junit.jupiter.api.Order(11)
+  void actualCoreGuidedSameSecretIdStaysWithinPersistedScope() throws Exception {
+    p3Case(() -> {
+      List<VaultScope> scopes = new java.util.ArrayList<>();
+      List<String> canaries = new java.util.ArrayList<>();
+      int ordinal = 0;
+      for (var axis : List.of(Map.entry("CSI-123", "fixture"), Map.entry("CSI-456", "fixture"),
+          Map.entry("CSI-123", "fixture-other"), Map.entry("CSI-123", "fixture"))) {
+        p3Mode = P3Mode.LOGIN;
+        p3Grant(axis.getKey(), axis.getValue());
+        UUID test = p3CreateSource(axis.getKey(), axis.getValue(), true);
+        VaultScope scope = VaultScope.of(axis.getKey(), axis.getValue(), test);
+        String value = "P3-SCOPED-" + UUID.randomUUID();
+        canaries.add(value);
+        scopes.add(scope);
+        p3ExpectedPassword = value;
+        P3_RECEIPTS.clear();
+        P3_NATIVE_SESSIONS.clear();
+        p3Seed(scope, value);
+        int read = COUNTED_VAULT.readCount(StudioVaultProvider.ReferenceKind.SECRET, scope, "PASS");
+        List<Integer> foreignReads = scopes.stream().map(other -> COUNTED_VAULT.readCount(
+            StudioVaultProvider.ReferenceKind.SECRET, other, "PASS")).toList();
+        String id = p3Start(test, axis.getValue());
+        awaitFinalizing(id);
+        assertThat(COUNTED_VAULT.readCount(StudioVaultProvider.ReferenceKind.SECRET, scope, "PASS") - read).isEqualTo(1);
+        assertThat(P3_RECEIPTS).hasSize(1);
+        assertThat(P3_RECEIPTS.getFirst().accepted()).isTrue();
+        assertThat(P3_RECEIPTS.getFirst().password().equals(value)).isTrue();
+        assertThat(P3_RECEIPTS.getFirst().username().equals("p3-user")).isTrue();
+        for (int i = 0; i < scopes.size() - 1; i++) {
+          assertThat(COUNTED_VAULT.readCount(StudioVaultProvider.ReferenceKind.SECRET, scopes.get(i), "PASS"))
+              .isEqualTo(foreignReads.get(i));
+        }
+        assertThat(COUNTED_VAULT.lists.stream().anyMatch(scope::equals)).isTrue();
+        p3AssertUsed(id, null);
+        p3AssertAuditScope(id, null, scope);
+        p3Publish(id);
+        p3Scan(canaries);
+        // Missing test scope is a real names-only refusal, not a value read or a malformed policy.
+        UUID missing = p3CreateSource(axis.getKey(), axis.getValue(), true);
+        int values = COUNTED_VAULT.reads.size(), calls = MODEL_WIRE.size();
+        JsonNode refusal = p3Call(p3Cookie, "/api/v3/studio/guided-sessions", p3StartCommand(missing, axis.getValue()), 404);
+        assertThat(refusal.path("code").asText()).isEqualTo("SECRET_UNAVAILABLE");
+        assertThat(COUNTED_VAULT.reads.size()).isEqualTo(values);
+        assertThat(MODEL_WIRE.size()).isEqualTo(calls);
+        assertThat(jdbc.queryForObject("SELECT count(*) FROM studio_guided_sessions WHERE test_id=?",
+            Long.class, missing.toString())).isZero();
+        p3WriteEvidence("guided-scope-" + (++ordinal), C.object().put("ordinal", ordinal)
+            .put("ownReads", COUNTED_VAULT.readCount(StudioVaultProvider.ReferenceKind.SECRET, scope, "PASS") - read)
+            .put("foreignReads", 0).put("acceptedPosts", P3_RECEIPTS.stream().filter(P3Receipt::accepted).count())
+            .put("missingScopeValueReads", COUNTED_VAULT.reads.size() - values)
+            .put("namesLookupObserved", COUNTED_VAULT.lists.stream().anyMatch(scope::equals)));
+      }
+    });
