+  @Test
+  @org.junit.jupiter.api.Order(12)
+  void actualCoreOrdinarySameSecretIdStaysWithinAcceptedScope() throws Exception {
+    p3Case(() -> {
+      List<VaultScope> scopes = new java.util.ArrayList<>();
+      List<String> canaries = new java.util.ArrayList<>();
+      int ordinal = 0;
+      for (var axis : List.of(Map.entry("CSI-123", "fixture"), Map.entry("CSI-456", "fixture"),
+          Map.entry("CSI-123", "fixture-other"), Map.entry("CSI-123", "fixture"))) {
+        p3Mode = P3Mode.LOGIN;
+        p3Grant(axis.getKey(), axis.getValue());
+        UUID test = p3CreateSource(axis.getKey(), axis.getValue(), true);
+        VaultScope scope = VaultScope.of(axis.getKey(), axis.getValue(), test);
+        scopes.add(scope);
+        String value = "P3-ORDINARY-" + UUID.randomUUID();
+        canaries.add(value);
+        p3ExpectedPassword = value;
+        P3_RECEIPTS.clear();
+        P3_NATIVE_SESSIONS.clear();
+        p3Seed(scope, value);
+        String id = p3Start(test, axis.getValue());
+        awaitFinalizing(id);
+        P3Publication published = p3Publish(id);
+        int models = MODEL_WIRE.size();
+        P3_NATIVE_SESSIONS.clear();
+        P3_RECEIPTS.clear();
+        List<Integer> beforeReads = scopes.stream().map(other -> COUNTED_VAULT.readCount(
+            StudioVaultProvider.ReferenceKind.SECRET, other, "PASS")).toList();
+        UUID execution = p3Execute(test);
+        p3AssertBinding(execution, scope, published);
+        assertThat(COUNTED_VAULT.readCount(StudioVaultProvider.ReferenceKind.SECRET, scope, "PASS"))
+            .isEqualTo(beforeReads.getLast());
+        assertThat(dispatcher.dispatchOnce()).isEqualTo(1);
+        JsonNode report = p3AwaitExecution(execution, "PASSED");
+        assertThat(COUNTED_VAULT.readCount(StudioVaultProvider.ReferenceKind.SECRET, scope, "PASS"))
+            .isEqualTo(beforeReads.getLast() + 1);
+        for (int i = 0; i < scopes.size() - 1; i++) {
+          assertThat(COUNTED_VAULT.readCount(StudioVaultProvider.ReferenceKind.SECRET, scopes.get(i), "PASS"))
+              .isEqualTo(beforeReads.get(i));
+        }
+        assertThat(P3_RECEIPTS).hasSize(1);
+        assertThat(P3_RECEIPTS.getFirst().accepted()).isTrue();
+        assertThat(P3_RECEIPTS.getFirst().password().equals(value)).isTrue();
+        assertThat(P3_RECEIPTS.getFirst().username().equals("p3-user")).isTrue();
+        p3AssertUsed(null, execution);
+        p3AssertAuditScope(null, execution, scope);
+        p3DecodeVideo(execution, report);
+        assertThat(MODEL_WIRE.size()).isEqualTo(models);
+        // Genuine accepted scope remains fixed when its own entry vanishes at the actual read.
+        P3_NATIVE_SESSIONS.clear();
+        P3_RECEIPTS.clear();
+        p3Seed(scope, value);
+        UUID unavailable = p3Execute(test);
+        p3AssertBinding(unavailable, scope, published);
+        int reads = COUNTED_VAULT.readCount(StudioVaultProvider.ReferenceKind.SECRET, scope, "PASS");
+        P3_FAIL_READ.set(scope);
+        assertThat(dispatcher.dispatchOnce()).isEqualTo(1);
+        JsonNode refused = p3AwaitExecution(unavailable, "ERROR");
+        assertThat(refused.path("errorCode").asText()).isEqualTo("REFERENCE_UNAVAILABLE");
+        assertThat(COUNTED_VAULT.readCount(StudioVaultProvider.ReferenceKind.SECRET, scope, "PASS") - reads).isEqualTo(1);
+        assertThat(P3_FAIL_READ.get()).isNull();
+        assertThat(P3_RECEIPTS).isEmpty();
+        for (int i = 0; i < scopes.size() - 1; i++) {
+          assertThat(COUNTED_VAULT.readCount(StudioVaultProvider.ReferenceKind.SECRET, scopes.get(i), "PASS"))
+              .isEqualTo(beforeReads.get(i));
+        }
+        assertThat(ACTUAL_DISPATCH_DIAGNOSTICS.containsKey(unavailable)).isFalse();
+        assertThat(jdbc.queryForObject("SELECT browser_started_at IS NULL AND observed_admission_receipt IS NULL"
+            + " FROM ui_test_executions WHERE id=?", Boolean.class, unavailable)).isTrue();
+        assertThat(jdbc.queryForObject("SELECT count(*) FROM studio_secret_use_audit WHERE execution_id=?"
+            + " AND row_kind='RELEASE' AND outcome='UNAVAILABLE'", Long.class, unavailable)).isEqualTo(1);
+        p3AssertAuditScope(null, unavailable, scope);
+        p3Seed(scope, value);
+        String denied = p3CoreCookie("p3-denied-ordinary", "p3-denied-ordinary@example.invalid");
+        long accepted = jdbc.queryForObject("SELECT count(*) FROM ui_test_executions WHERE ui_test_id=?", Long.class, test);
+        int deniedReads = COUNTED_VAULT.reads.size();
+        JsonNode noPermission = p3Call(denied, "/api/v1/studio/tests/" + test + "/execute", C.object(), 400);
+        assertThat(noPermission.path("error").asText()).isEqualTo("UNKNOWN_REFERENCE");
+        assertThat(jdbc.queryForObject("SELECT count(*) FROM ui_test_executions WHERE ui_test_id=?", Long.class, test))
+            .isEqualTo(accepted);
+        assertThat(COUNTED_VAULT.reads.size()).isEqualTo(deniedReads);
+        assertThat(MODEL_WIRE.size()).isEqualTo(models);
+        p3Scan(canaries);
+        p3WriteEvidence("ordinary-scope-" + (++ordinal), C.object().put("ordinal", ordinal)
+            .put("successfulOwnRead", reads - beforeReads.getLast())
+            .put("foreignReads", 0)
+            .put("missingOwnRead", COUNTED_VAULT.readCount(StudioVaultProvider.ReferenceKind.SECRET, scope, "PASS") - reads)
+            .put("missingOwnSends", ACTUAL_DISPATCH_DIAGNOSTICS.containsKey(unavailable) ? 1 : 0)
+            .put("deniedPrincipalReads", COUNTED_VAULT.reads.size() - deniedReads)
+            .put("artifactUnchanged", jdbc.queryForObject("SELECT artifact_hash FROM ui_test_revisions WHERE id=?",
+                String.class, published.revision()).equals(published.artifactHash())));
+      }
+    });
+  }
