+  private JsonNode p3Call(String cookie, String path, JsonNode body, int status) throws Exception {
+    var request = HttpRequest.newBuilder(URI.create("https://localhost:" + port + path)).timeout(Duration.ofSeconds(15))
+        .header("Cookie", "put_session=" + cookie);
+    if (body == null) {
+      request.GET();
+    } else {
+      request.header("Content-Type", "application/json").header("Idempotency-Key", UUID.randomUUID().toString())
+          .POST(HttpRequest.BodyPublishers.ofString(body.toString()));
+    }
+    var response = HttpClient.newBuilder().sslContext(TLS).build().send(request.build(), HttpResponse.BodyHandlers.ofString());
+    assertThat(response.statusCode()).as("actual P3 public route status").isEqualTo(status);
+    JsonNode parsed = C.parse(response.body());
+    if (path.equals("/api/v3/studio/guided-sessions") && status == 202) {
+      String id = parsed.path("session").path("sessionId").asText();
+      assertThat(id).isNotBlank();
+      testOwnedSessions.put(id, parsed.path("session").path("testId").asText());
+    }
+    return parsed;
+  }
