4292:   private JsonNode p3Call(String cookie, String path, JsonNode body, int status) throws Exception {
4293:     var request =
4294:         HttpRequest.newBuilder(URI.create("https://localhost:" + port + path))
4295:             .timeout(Duration.ofSeconds(15))
4296:             .header("Cookie", "put_session=" + cookie);
4297:     if (body == null) {
4298:       request.GET();
4299:     } else {
4300:       request
4301:           .header("Content-Type", "application/json")
4302:           .header("Idempotency-Key", UUID.randomUUID().toString())
4303:           .POST(HttpRequest.BodyPublishers.ofString(body.toString()));
4304:     }
4305:     var response =
4306:         HttpClient.newBuilder()
4307:             .sslContext(TLS)
4308:             .build()
4309:             .send(request.build(), HttpResponse.BodyHandlers.ofString());
4310:     assertThat(response.statusCode()).as("actual P3 public route status").isEqualTo(status);
4311:     JsonNode parsed = C.parse(response.body());
4312:     if (path.equals("/api/v3/studio/guided-sessions") && status == 202) {
4313:       String id = parsed.path("session").path("sessionId").asText();
4314:       assertThat(id).isNotBlank();
4315:       testOwnedSessions.put(id, parsed.path("session").path("testId").asText());
4316:     }
4317:     return parsed;
