4564:   private static void p3Application(com.sun.net.httpserver.HttpExchange exchange)
4565:       throws IOException {
4566:     try {
4567:       if (p3Mode == null) {
4568:         exchange.sendResponseHeaders(404, -1);
4569:         return;
4570:       }
4571:       String path = exchange.getRequestURI().getPath();
4572:       String document;
4573:       if (path.equals("/p3/login") && exchange.getRequestMethod().equals("POST")) {
4574:         String raw = new String(exchange.getRequestBody().readAllBytes(), StandardCharsets.UTF_8);
4575:         var values = new java.util.HashMap<String, String>();
4576:         for (String pair : raw.split("&")) {
4577:           String[] parts = pair.split("=", 2);
4578:           values.put(
4579:               java.net.URLDecoder.decode(parts[0], StandardCharsets.UTF_8),
4580:               java.net.URLDecoder.decode(
4581:                   parts.length == 2 ? parts[1] : "", StandardCharsets.UTF_8));
4582:         }
4583:         String password = values.getOrDefault("password", "");
4584:         boolean accepted = password.equals(p3ExpectedPassword);
4585:         P3_RECEIPTS.add(new P3Receipt(password, values.getOrDefault("username", ""), accepted));
4586:         if (accepted) {
4587:           String session = UUID.randomUUID().toString();
4588:           P3_NATIVE_SESSIONS.add(session);
4589:           exchange
4590:               .getResponseHeaders()
4591:               .set(
4592:                   "Set-Cookie", "p3_session=" + session + "; HttpOnly; SameSite=Strict; Path=/p3/");
4593:           exchange.getResponseHeaders().set("Location", "/p3/home");
4594:           exchange.sendResponseHeaders(302, -1);
4595:           return;
4596:         }
4597:         document = p3LoginDocument();
4598:       } else if (path.equals("/p3/registration")) {
4599:         document = p3LoginDocument() + "<h1>Registration</h1>";
4600:       } else if (path.equals("/p3/login")) {
4601:         document = p3LoginDocument();
4602:       } else {
4603:         String cookies = exchange.getRequestHeaders().getFirst("Cookie");
4604:         boolean signedIn =
4605:             cookies != null
4606:                 && java.util.Arrays.stream(cookies.split(";"))
4607:                     .map(String::trim)
4608:                     .filter(cookie -> cookie.startsWith("p3_session="))
4609:                     .map(cookie -> cookie.substring("p3_session=".length()))
4610:                     .anyMatch(P3_NATIVE_SESSIONS::contains);
4611:         if ((!path.equals("/p3/reports") || p3ReportsProtected) && !signedIn) {
4612:           exchange.getResponseHeaders().set("Location", "/p3/login");
4613:           exchange.sendResponseHeaders(302, -1);
4614:           return;
4615:         }
4616:         if (path.equals("/p3/home")) {
4617:           document = "<main><h1>Home</h1><a href='/p3/reports'>Reports</a></main>";
4618:         } else if (path.equals("/p3/reports")) {
4619:           P3_REPORT_REQUESTS.incrementAndGet();
4620:           document = "<main><h1>Reports</h1><p>Protected report</p></main>";
4621:         } else {
4622:           exchange.sendResponseHeaders(404, -1);
4623:           return;
4624:         }
